if _, err := r.serve(r.sign(rolloutPublishKind, rolloutPublishRequest{Receipt: []byte("receipt:" + second)}, nil)); err != nil {
	t.Fatal(err)
}
if reply, err := r.serve(r.sign(rolloutPauseKind, struct{}{}, nil)); err != nil || reply.Status != "paused" || !reply.Paused {
	t.Fatalf("pause = %+v %v", reply, err)
}
reply, err = r.serve(r.sign(rolloutRollbackKind, rolloutRollbackRequest{To: 1}, nil))
if err != nil || reply.Status != "rolled-back" || reply.Desired.Generation != 3 || reply.Desired.RollbackOf != 1 ||
	reply.Desired.Digest != first || reply.Desired.RunNumber != 9 || !reply.Paused || len(reply.History) != 3 {
	t.Fatalf("rollback = %+v %v", reply, err)
}
if reply, err := r.serve(r.sign(rolloutResumeKind, struct{}{}, nil)); err != nil || reply.Status != "resumed" || reply.Paused {
	t.Fatalf("resume = %+v %v", reply, err)
}
if reply, err := r.serve(r.sign(rolloutStatusKind, struct{}{}, nil)); err != nil || reply.Status != "" || reply.Desired.Generation != 3 {
	t.Fatalf("status = %+v %v", reply, err)
}

if _, err := r.serve(r.sign(rolloutPublishKind, rolloutPublishRequest{Receipt: []byte("receipt:" + strings.Repeat("b", 64))}, nil)); err != nil {
	t.Fatal(err)
}
r.control.verify = func(receipt, _ []byte, _ time.Time) (rollout.Release, error) {
	if strings.HasSuffix(string(receipt), digest) {
		return rollout.Release{}, errors.New("delegation expired")
	}
	return testReceiptDigest(receipt, nil, time.Time{})
}
if _, err := r.serve(r.sign(rolloutRollbackKind, rolloutRollbackRequest{To: 1}, nil)); err == nil || !strings.Contains(err.Error(), "no longer verifies") {
	t.Fatalf("rollback to an expired receipt: %v", err)
}
if desired, _, err := r.control.store.Load().Desired(t.Context()); err != nil || desired.Generation() != 2 {
	t.Fatalf("a refused rollback moved the cell: %+v %v", desired, err)
}

// Without release roots nothing is published; without the store
// nothing is answered.
r.control.verify = nil
if _, err := r.serve(r.sign(rolloutPublishKind, publish, nil)); err == nil || !strings.Contains(err.Error(), "trust roots") {
	t.Fatalf("publish without roots: %v", err)
}
r.control.store.Store(nil)
if _, err := r.serve(r.sign(rolloutStatusKind, struct{}{}, nil)); err == nil || !strings.Contains(err.Error(), "not open") {
	t.Fatalf("status without a store: %v", err)
}

command("publish", "bad", 0)
waitPhase(entityid.Derive("release-controllers", rollout.ReleaseRolloutID(2)), rollout.PhaseRolledBack)
waitSettled("good")
if moved := starts.on(digests["bad"]); !slices.Equal(moved, []string{"ctl-b"}) {
	t.Fatalf("units that ran the bad release = %v, want the canary only", moved)
}
if bad, err := units["ctl-b"].layout.KnownBad(); err != nil || !bad[digests["bad"]] {
	t.Fatalf("the canary's node does not refuse the bad release: %v %v", bad, err)
}
// The next tick reports why the program stopped.
for {
	status := command("status", "", 0)
	if !status.DesiredKnownBad || status.Desired.Digest != digests["bad"] {
		t.Fatalf("status does not report the rejected release: %+v", status)
	}
	if status.Rollout != nil && strings.Contains(status.Rollout.Waiting, entityid.Derive("release-controllers", rollout.ReleaseRolloutID(2))+" stopped the program: rollout ended rolled-back") {
		break
	}
	if ctx.Err() != nil {
		t.Fatalf("status does not say why nothing runs: %+v", status.Rollout)
	}
	time.Sleep(200 * time.Millisecond)
}

// A paused cell starts nothing until it is resumed.
if reply := command("pause", "", 0); reply.Status != "paused" || !reply.Paused {
	t.Fatalf("pause = %+v", reply)
}
command("publish", "good2", 0)
time.Sleep(2 * time.Second)
if moved := starts.on(digests["good2"]); len(moved) != 0 {
	t.Fatalf("a paused cell moved %v", moved)
}
if reply := command("resume", "", 0); reply.Status != "resumed" || reply.Paused {
	t.Fatalf("resume = %+v", reply)
}
waitPhase(entityid.Derive("release-controllers", rollout.ReleaseRolloutID(3)), rollout.PhaseComplete)
waitSettled("good2")

// Rolling back to generation 1 is a new generation.
reply := command("rollback", "", 1)
if reply.Status != "rolled-back" || reply.Desired == nil || reply.Desired.Generation != 4 ||
	reply.Desired.RollbackOf != 1 || reply.Desired.Digest != digests["good"] {
	t.Fatalf("rollback = %+v", reply)
}
waitPhase(entityid.Derive("release-controllers", rollout.ReleaseRolloutID(4)), rollout.PhaseComplete)
waitSettled("good")
history := command("status", "", 0).History
var generations []uint64
for _, release := range history {
	generations = append(generations, release.Generation)
	if release.Receipt != nil {
		t.Fatal("status carries release receipts")
	}
}
if !slices.Equal(generations, []uint64{4, 3, 2, 1}) {
	t.Fatalf("history = %v", generations)
}

status, revision := f.report(t)
if status.RunNumber != wantRun || status.Pins == nil || !slices.Equal(status.Pins.Rollback, wantRollback) ||
	!present && status.Reason != "the cell has no release channel" {
	t.Fatalf("initialized report = %+v, pins = %+v", status, status.Pins)
}
if present {
	update(nil)
	if after, got := f.report(t); got != revision || !sameReport(status, after) {
		t.Fatalf("completion marker changed the channel report: %+v", after)
	}
	update(deletedChannelEntry{initial})
	status, revision = f.report(t)
	if status.RunNumber != 0 || status.Reason != "the cell has no release channel" {
		t.Fatalf("deleted channel report = %+v", status)
	}
}
bad := strings.Repeat("e", 64)
if _, err := f.rolloutKV.Put(ctx, "knownbad."+bad, []byte(`{}`)); err != nil {
	t.Fatal(err)
}
f.control.ticks <- struct{}{}
next()
refreshed, got := f.report(t)
if got == revision || refreshed.Reason != status.Reason || refreshed.Pins == nil ||
	!slices.Equal(refreshed.Pins.Rollback, wantRollback) || !slices.Equal(refreshed.Pins.KnownBad, []string{bad}) {
	t.Fatalf("pin-only tick report = %+v, pins = %+v", refreshed, refreshed.Pins)
}
fencer.set(followerLeadership{}.Current())
f.control.ticks <- struct{}{}
next()
if _, after := f.report(t); after != got || f.control.reported.Load() != nil {
	t.Fatal("follower changed the report or retained the leader's local status")
}
if present {
	cancel()
} else {
	close(watcher.updates)
}
select {
case <-done:
case <-time.After(5 * time.Second):
	t.Fatal("consumer did not stop after watcher closure or cancellation")
